import{_ as t,o,c as d,a2 as n}from"./chunks/framework.Buc7gXeZ.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-record-view/troubleshooting.md","filePath":"dynamic-record-view/troubleshooting.md"}'),i={name:"dynamic-record-view/troubleshooting.md"};function a(c,e,r,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Status: <strong>Implemented</strong> — real exceptions this engine actually throws.</p><table tabindex="0"><thead><tr><th>Symptom / Exception</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>UnknownRecordViewKeyException</code></td><td><code>RecordViewRegistry::resolve($key)</code> called with a key never <code>register()</code>-ed.</td><td>Register the view in the owning module&#39;s service provider <code>boot()</code> (see <code>Modules\\General\\Providers\\GeneralServiceProvider</code>).</td></tr><tr><td>404 on a record you expect to see</td><td><code>DynamicRecordView::query()</code> excludes the row (soft delete, tenant scope, explicit authorization <code>where()</code>). This is intentional fail-closed behavior — see <a href="./security">security.md</a> — not distinguishable from &quot;doesn&#39;t exist&quot;.</td><td>Check the view&#39;s <code>query()</code> scopes match what the current user should see.</td></tr><tr><td><code>MultipleDefaultTabsException</code></td><td>More than one <code>RecordTab::default()</code> in the same <code>RecordSection</code>.</td><td>Only one tab per section may call <code>-&gt;default()</code>.</td></tr><tr><td><code>NoAuthorizedDefaultTabException</code></td><td>Every tab in a section is unauthorized for the resolved record.</td><td>At least one tab&#39;s <code>visible()</code> condition must pass, or the section shouldn&#39;t render for this record/user at all.</td></tr><tr><td><code>DuplicateTabKeyException</code> / <code>DuplicateContentKeyException</code> / <code>DuplicateFieldKeyException</code></td><td>Two tabs/content blocks/fields in the same collection share a key.</td><td>Keys must be unique within their container.</td></tr><tr><td><code>UnknownTableException</code></td><td>An embedded <code>Table</code>&#39;s class doesn&#39;t match what the <code>TableContent</code> declared.</td><td>Check <code>TableContent::table()</code> matches the actual <code>embedTableClass</code> prop passed.</td></tr><tr><td><code>UnknownRelationException</code></td><td><code>SubApplication::relation(&#39;name&#39;)</code>/<code>TableContent::relation(&#39;name&#39;)</code> names a method that isn&#39;t a relation on the parent model.</td><td>Check the relation method name and that it returns a <code>Relation</code>.</td></tr><tr><td><code>UnsupportedRelationTypeException</code></td><td>The named relation isn&#39;t <code>HasMany</code>, <code>BelongsToMany</code>, or <code>MorphMany</code>.</td><td>Only those three relation types are supported for embedding/Link/Unlink.</td></tr><tr><td><code>TableModelMismatchException</code></td><td>The embedded <code>Table</code>&#39;s base-query model doesn&#39;t match the relation&#39;s related model.</td><td>The <code>Table</code> subclass must query the same model the relation returns.</td></tr><tr><td><strong>Unlink button missing / 422 on Unlink</strong></td><td>The relation&#39;s foreign key is <code>NOT NULL</code> (e.g. <code>Application.submodule_id</code>, <code>City.country_id</code>). Setting it to <code>null</code> to &quot;unlink&quot; would violate the schema — this is a real, permanent limitation, not a bug.</td><td>Don&#39;t call <code>-&gt;unlinkable()</code> for a non-nullable FK relation. Use <code>-&gt;allowReassignment()</code> with Link instead — re-pointing the FK to a different parent is the only valid &quot;move&quot; operation. See <a href="./security">security.md</a>, <a href="./relationship-actions">relationship-actions.md</a>.</td></tr><tr><td><code>HttpException(422, &#39;Unable to complete this action.&#39;)</code> from a Link/Unlink attempt</td><td>Generic, deliberately non-specific failure from <code>RelationshipMutator::safeAbortUnless()</code> — could be: parent/candidate no longer exists, <code>linkAuthorization()</code>/<code>unlinkAuthorization()</code> returned false, or the candidate is already linked to a different parent without <code>allowReassignment()</code>.</td><td>Check server logs / add a temporary non-generic check in a test if you need to pin down which guard failed — the generic message is intentional in production to prevent id-probing.</td></tr><tr><td>A <code>LinkViewField</code> renders no link at all</td><td>The URL failed <code>LinkViewField::isSafeUrl()</code> — wrong scheme (not http/https/mailto/tel), contains control characters, or is empty.</td><td>Check what <code>linkUsing()</code> actually returns; this is fail-closed by design, not a bug. See <a href="./security">security.md</a>.</td></tr><tr><td>Lazy-loading violation / N+1 on a <code>RelationViewField</code></td><td>The relation wasn&#39;t picked up by <code>DynamicRecordView::requiredEagerLoads()</code> — only relations named by a <code>RelationViewField</code> inside a <code>FieldsContent</code> on <code>tabs()</code> are auto-collected; Other Data section relations are loaded separately per embedded table.</td><td>See <a href="./performance">performance.md</a>. If you hit this on a genuinely new pattern, extend <code>requiredEagerLoads()</code>.</td></tr><tr><td><code>MissingViewKeyException</code></td><td><code>DynamicRecordView::getViewKey()</code> called before <code>$viewKey</code> is set.</td><td>Set <code>protected string $viewKey = &#39;...&#39;</code> on the concrete class.</td></tr></tbody></table>',3)])])}const m=t(i,[["render",a]]);export{p as __pageData,m as default};
